with prev_events as (select *, lag(paid_at) over (partition by method order by paid_at, id) as prev_paid_at from payments), flagged as (select *, case when prev_paid_at is null or paid_at > prev_paid_at + interval '60' day then 1 else 0 end as session_start_flag from prev_events), sessionized as (select *, sum(session_start_flag) over (partition by method order by paid_at, id rows between unbounded preceding and current row) as session_no from flagged) select status, min(prev_paid_at) as started_at, approx_percentile(session_start_flag, 0.9) as session_start_flag_p90, grouping_id() as gid from sessionized group by cube (status) order by status nulls first
